<?php
declare(strict_types=1); require_once __DIR__ . '/../../helpers/auth.php'; require_once __DIR__ . '/../../helpers/csrf.php'; require_once __DIR__ . '/../../models/Announcement.php'; require_role(['SUPER_ADMIN','CHURCH_ADMIN','STAFF']); $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $item=$id?database()->query('SELECT * FROM announcements WHERE id='.(int)$id)->fetch():[]; if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf_token(); $audience=$_POST['audience_role']?:null; if($audience && !in_array($audience,Announcement::AUDIENCES,true))exit('Invalid audience.'); Announcement::save(['user_id'=>(int)current_user_id(),'title'=>trim($_POST['title']),'body'=>trim($_POST['body']),'audience_role'=>$audience,'published_at'=>$_POST['published_at']?:null,'expires_at'=>$_POST['expires_at']?:null,'status'=>$_POST['announcement_status']],$id?:null); header('Location: index.php');exit;} $pageTitle=$id?'Edit announcement':'Create announcement'; require __DIR__ . '/../../includes/header.php'; ?><div class="cmmp-page-header"><h1><?=e($pageTitle)?></h1></div><div class="cmmp-card"><form method="post"><?=csrf_field()?><input class="form-control mb-3" name="title" placeholder="Title" value="<?=e($item['title']??'')?>" required><textarea class="form-control mb-3" name="body" rows="6" required><?=e($item['body']??'')?></textarea><select class="form-select mb-3" name="audience_role"><option value="">ALL</option><?php foreach(Announcement::AUDIENCES as $audience): ?><option <?=($item['audience_role']??'')===$audience?'selected':''?>><?=e($audience)?></option><?php endforeach; ?></select><div class="row g-3"><div class="col-md-4"><label>Publish at</label><input class="form-control" type="datetime-local" name="published_at" value="<?=e(str_replace(' ','T',$item['published_at']??''))?>"></div><div class="col-md-4"><label>Expires at</label><input class="form-control" type="datetime-local" name="expires_at" value="<?=e(str_replace(' ','T',$item['expires_at']??''))?>"></div><div class="col-md-4"><label>Status</label><select class="form-select" name="announcement_status"><option>DRAFT</option><option <?=($item['announcement_status']??'')==='PUBLISHED'?'selected':''?>>PUBLISHED</option><option <?=($item['announcement_status']??'')==='ARCHIVED'?'selected':''?>>ARCHIVED</option></select></div></div><button class="btn btn-primary mt-3">Save announcement</button></form></div><?php require __DIR__ . '/../../includes/footer.php'; ?>
